\mathrm{df\text{-}metric\text{-}compactness\text{-}principles}\vdash\;\begin{aligned}
\mathrm{MSC}&\coloneqq\forall\mathcal A\forall F[(\mathsf{Compact}(\mathcal A)\land\mathsf{PtSeq}_{\mathcal A}(F))\to\exists g\exists x\;\mathsf{SubConv}_{\mathcal A}(F,g,x)],\\
\mathrm{MCC}&\coloneqq\forall\mathcal A\forall F[(\mathsf{Met}(\mathcal A)\land\mathsf{Cauchy}_{\mathcal A}(F))\to\exists x\;\mathsf{Conv}_{\mathcal A}(F,x)],\\
\mathrm{MHB}&\coloneqq\forall\mathcal A\forall C[(\mathsf{Compact}(\mathcal A)\land\mathsf{Cover}_{\mathcal A}(C))\to\exists l\forall x(\mathsf{Pt}_{\mathcal A}(x)\to\exists i\le l\;x\in_{\mathcal A}(C)_i)].
\end{aligned}
